  2	import java.util.HashMap;
  3	import java.util.Iterator;
  4	import java.util.List;
  5	
  6	/**
  7	 * A class representing shared characteristics of animals.
  8	 *
  9	 * @version 2022.03.01
 10	 */
 11	public abstract class Animal extends Actor
 12	{
 13	    private double foodLevel;
 14	    private boolean isGirl;
 15	    private boolean isHealthy;
 16	    //the number of steps an animal takes when infected.
 17	    private int infectedStepCounter;
 18	    //how many steps animal needs to wait before it can breed again.
 19	    private int timeLeftUntilBreedingAgain = 0;
 20	    /**
 21	     * Create a new animal at location in field.
 22	     * 
 23	     * @param field The field currently occupied.
 24	     * @param location The location within the field.
 25	     */
 26	    public Animal(Field field, Location location)
 27	    {
 28	        super(field,location);
 29	        setRandomGender();
 30	        isHealthy = true;
 31	        infectedStepCounter = 0;
 32	        timeLeftUntilBreedingAgain= getRandom().nextInt(getMaxTimeUntilBreedingAgain());
 33	        if(!isGirl){
 34	        timeLeftUntilBreedingAgain = 0;
 35	        }
 36	    }
 37	
 38	    /**
 39	     * Make this animal act - that is: make it do
 40	     * whatever it wants/needs to do.
 41	     * @param newActors A list to receive newly born animals.
 42	     * @param simulator The simulator.
 43	     */
 44	    public void act(List<Actor> newActors, Simulator simulator) {
 45	        addGrowthLevel(getGrowthRate());
 46	        if(simulator.isDay()) {
 47	            incrementAge(simulator.getSteps());
 48	            incrementHunger();
 49	            if(isActive()) {
 50	                giveBirth(newActors);
 51	                Location newLocation = findFood(getFoodProbability(simulator.getWeather()));
 52	                if(newLocation == null) {
 53	                    newLocation = getField().freeAdjacentLocation(getLocation());
 54	                }
 55	                if(newLocation != null) {
 56	                    setLocation(newLocation);
 57	                } else {
 58	                    setDead();
 59	                }
 60	            }
 61	        }
 62	    }
 63	
 64	    abstract protected double getGrowthRate();
 65	
 66	    abstract protected double getFoodProbability(Weather weather);
 67	
 68	    /**
 69	     * An animal can breed if it has reached the breeding age.
 70	     * @return true if an animal is able to breed
 71	     */
 72	    protected boolean canBreed()
 73	    {
 74	        return getAge() >= getBreedingAge();
 75	    }
 76	
 77	    /**
 78	     * Get breeding age of an animal.
 79	     * @return int. Breeding age of the animal;
 80	     */
 81	    abstract protected int getBreedingAge();
 82	
 83	    /**
 84	     * Check whether or not this animal is to give birth at this step.
 85	     * New births will be made into free adjacent locations.
 86	     * @param newAnimals A list to return newly born animals.
 87	     */
 88	    protected void giveBirth(List<Actor> newAnimals)
 89	    {
 90	        // New animals are born into adjacent locations.
 91	        // Get a list of adjacent free locations.
 92	        Field field = getField();
 93	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
 94	        if (timeLeftUntilBreedingAgain != 0){
 95	            timeLeftUntilBreedingAgain --;
 96	        }
 97	        int births = breed();
 98	        for(int b = 0; b < births && free.size() > 0; b++) {
 99	            Location loc = free.remove(0);
100	            Animal baby = createOffspring(field, loc);
101	            if(!getHealth()){
102	                baby.setUnhealthy();
103	            }
