  8	/**
  9	 * A simple model of a Hunter.
 10	 * Hunters age, move, hunt lions, and die.
 11	 * Hunters can bring other hunters after 898 steps to increse the hunter population.
 12	 *
 13	 * @version 2022.03.01
 14	 */
 15	public class Hunter extends Actor
 16	
 17	{
 18	    // Characteristics shared by all Hunters.
 19	    private static final int MAX_AGE = 1000;
 20	    private static final int SHOTS = 2;
 21	    private static final Set<Class<? extends Actor>> HUNTABLE_SPECIES = new HashSet<>(Arrays.asList(Lion.class, Cheetah.class));
 22	    /**
 23	     * Create a Hunter. A hunter is created as an adult (age 50).
 24	     * 
 25	     * @param field The field currently occupied.
 26	     * @param location The location within the field.
 27	     */
 28	    public Hunter(Field field, Location location)
 29	    {
 30	        super(field, location);
 31	        setAge(50);
 32	    }
 33	
 34	    /**
 35	     * This is what the Hunter does most of the time: it hunts
 36	     * lions during the night. In the process, it might die of old age.
 37	     * 
 38	     * @param newHunters A list to return new Hunters.
 39	     * @param simulator The simulator.
 40	     */
 41	    public void act(List<Actor> newHunters,Simulator simulator){
 42	        incrementAge(simulator.getSteps());
 43	        if(!simulator.isDay()){
 44	            if(isActive() ) {
 45	                hunt(getHuntProbability(simulator.getWeather()));
 46	                Field field = getField();
 47	                Location newLocation = field.freeAdjacentLocation(getLocation());
 48	                if(newLocation != null) {
 49	                    setLocation(newLocation);
 50	                } 
 51	                //hunter number increases as there are more hunters in the area who want to hunt.
 52	                if (simulator.getSteps() % 898 ==  0){
 53	                    List<Location> free = field.getFreeAdjacentLocations(getLocation());
 54	                    if(free.size() > 0) {
 55	                        Location loc = free.remove(0);
 56	                        Hunter hunter = new Hunter(field, loc);
 57	                        newHunters.add(hunter);
 58	                    }
 59	                }
 60	            }
 61	        }
 62	    }
 63	
 64	    private double getHuntProbability(Weather weather) {
 65	        switch(weather) {
 66	            case RAINY: return 0.7;
 67	            case FOGGY: return 0.4;
 68	            default:    return getRandom().nextDouble();
 69	        }
 70	    }
 71	
 72	    /**
 73	     * This determine how the hunter hunts nearby lions
 74	     * The hunter has 2 shots.
 75	     * @param probability The probability the hunting is successful.
 76	     */
 77	    private void hunt(double probability){
 78	        if(getRandom().nextDouble() < probability){
 79	            Field field = getField();
 80	            List<Location> adjacent = field.adjacentLocations(getLocation());
 81	            Iterator<Location> it = adjacent.iterator();
 82	            for(int i = 0; i < SHOTS && it.hasNext(); i++){
 83	                Location where = it.next();
 84	                Object animal = field.getObjectAt(where);
 85	                if(animal != null && HUNTABLE_SPECIES.contains(animal.getClass())){
 86	                    Animal currentAnimal = (Animal) animal;
 87	                    if(currentAnimal.isActive()) {
 88	                        currentAnimal.setDead();
 89	                        break;
 90	                    }
 91	                }
 92	            }
 93	        }
 94	    }
 95	
 96	    /**
 97	     * Gets the max age of a hunter.
 98	     * @return int. Max age of the hunter.
 99	     */
100	    protected int getMaxAge(){
101	        return MAX_AGE;
102	    }
103	}

